--- a/docs/agents/quality-gates.md
+++ b/docs/agents/quality-gates.md
@@ -37,6 +37,12 @@ and `scripts/check_goldens.py --quick` (skipped for docs-only commits).
 - `dart analyze` + dart format clean (explicit dirs — `yoclip/` is a
   standalone video workspace with its own toolchain); example app also
   `flutter analyze --no-fatal-infos --no-fatal-warnings`.
+- No test hardcodes a platform-specific tool flag without a portable
+  branch (gh-2404): `/usr/bin/time` is GNU on Linux CI but BSD on macOS —
+  BSD has no `-f` (`illegal option -- f`, exit 1) and takes `-l`.
+  Feature-detect (`--version` exits 0 only on GNU) or measure in the
+  harness itself; the hook must be green on BOTH hosts for the same diff,
+  or hook/CI parity is broken.
 - `dart test` green (integration-tagged excluded from test-core — issue
   #551: `test/integration/**` changes also run the `integration-mock` leg
   per-PR: no-key legs via `MockLlmServer`, `--exclude-tags llm,browser-ext,
diff --git a/scripts/load_drop_retry.sh b/scripts/load_drop_retry.sh
index f360a06408..7ca881ee33 100755
--- a/scripts/load_drop_retry.sh
+++ b/scripts/load_drop_retry.sh
@@ -194,6 +194,11 @@ run_streamed() {
   local runner_pid=$!
   if [ "$SPAM_LIMIT" -gt 0 ]; then
     (
+      # gh-2404 (macOS bash 3.2): the parent's teardown TERM must end this
+      # subshell as a CLEAN exit, not a signal death — bash 3.2 then prints
+      # a job notice quoting this whole subshell (the wedge phrase included)
+      # to stderr, where it double-counts as a second wedge kill.
+      trap 'exit 0' TERM
       # `read -t` is the poll timer: a BUILTIN — killing this subshell
       # mid-wait forks no `sleep` child for the job harness to report.
       # The timer fd is the watchdog-private O_RDWR fifo opened above
@@ -235,7 +240,9 @@ run_streamed() {
   local i
   for i in 1 2 3 4 5; do
     kill -0 "$tee_pid" 2>/dev/null || break
-    read -t 0.2 -u 3 || true
+    # gh-2404: bash 3.2 (macOS) rejects fractional -t — silence its error;
+    # the ladder still caps the drain at ~1 s on bash 4+ and 0 s on 3.2.
+    read -t 0.2 -u 3 2>/dev/null || true
   done
   exec 3<&- || true
   kill "$tee_pid" 2>/dev/null || true
diff --git a/test/scripts/load_drop_retry_test.dart b/test/scripts/load_drop_retry_test.dart
index 8e30dd11f2..6d4d2c2bac 100644
--- a/test/scripts/load_drop_retry_test.dart
+++ b/test/scripts/load_drop_retry_test.dart
@@ -298,6 +298,34 @@ Future<ProcessResult> runWrapper(

 List<String> invocations(String tmp) => File('$tmp/argv.log').readAsLinesSync();

+/// gh-2404: `/usr/bin/time` is GNU on Linux CI but BSD on macOS. GNU takes
+/// `-f '%U %S'`; BSD has no `-f` (`illegal option -- f`, exit 1) and takes
+/// `-l`. `--version` exits 0 only on GNU (BSD prints usage, exits 1).
+bool gnuTime() => Process.runSync('/usr/bin/time', ['--version']).exitCode == 0;
+
+/// CPU user+sys seconds from `/usr/bin/time` output — parses BOTH shapes:
+/// GNU `-f '%U %S'` (`0.01 0.02`) and BSD `-l` (the `x real x user x sys`
+/// line, before the rusage rows). Throws on an unparsable shape — never a
+/// silent 0.
+double parseCpuSeconds(String output) {
+  final bsd = RegExp(
+    r'^\s*([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys\s*$',
+    multiLine: true,
+  ).firstMatch(output);
+  if (bsd != null) {
+    return double.parse(bsd.group(2)!) + double.parse(bsd.group(3)!);
+  }
+  for (final line in output.trim().split('\n')) {
+    final parts = line.trim().split(RegExp(r'\s+'));
+    if (parts.length == 2 &&
+        double.tryParse(parts[0]) != null &&
+        double.tryParse(parts[1]) != null) {
+      return double.parse(parts[0]) + double.parse(parts[1]);
+    }
+  }
+  throw FormatException('unparsable /usr/bin/time output: "$output"');
+}
+
 void main() {
   late Directory tmp;
   setUp(() {
@@ -563,8 +591,14 @@ void main() {
     expect(r.stderr, contains('exit-handshake wedge'));
     expect(r.stderr, contains('healed'));
     expect(
-      RegExp('exit-handshake wedge').allMatches(r.stderr.toString()),
+      RegExp(
+        '^load_drop_retry: exit-handshake wedge',
+        multiLine: true,
+      ).allMatches(r.stderr.toString()),
       hasLength(1),
+      // Anchored on the message prefix: bash 3.2's job notice for a TERMed
+      // watchdog quotes the whole subshell source (phrase included) and
+      // must not count as a second kill (gh-2404).
