double parseCpuSeconds(String output) {
  final bsd = RegExp(
    r'^\s*([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys\s*$',
    multiLine: true,
  ).firstMatch(output);
  if (bsd != null) {
    return double.parse(bsd.group(2)!) + double.parse(bsd.group(3)!);
  }
  for (final line in output.trim().split('\n')) {
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.length == 2 &&
        double.tryParse(parts[0]) != null &&
        double.tryParse(parts[1]) != null) {
      return double.parse(parts[0]) + double.parse(parts[1]);
    }
  }
  throw FormatException('unparsable /usr/bin/time output: "$output"');
}

void expectClose(double actual, double expected, String label) {
  if ((actual - expected).abs() > 1e-9) throw 'FAIL $label: $actual vs $expected';
  print('OK   $label = $actual');
}

void expectThrows(void Function() f, String label) {
  try { f(); throw 'FAIL $label: did not throw'; } on FormatException { print('OK   $label throws FormatException'); }
}

void main() {
  expectClose(parseCpuSeconds('0.01 0.02\n'), 0.03, 'GNU shape');
  expectClose(parseCpuSeconds(
    '        1.20 real         0.80 user         0.30 sys\n'
    '             1261568  maximum resident set size\n'
    '                   0  messages sent\n'), 1.1, 'BSD shape');
  expectThrows(() => parseCpuSeconds(''), 'empty');
  expectThrows(() => parseCpuSeconds('garbage\n'), 'garbage');
  // GNU real output shape from /usr/bin/time -o (checked next probe)
}
EOF
dart parse_probe.dart

